import type { Session } from '@supabase/supabase-js';

export const identityApiUrl = (
  import.meta.env.VITE_IDENTITY_API_URL || 'https://api.wersee.com/v1/identity'
).replace(/\/+$/, '');

export type WerseeIdentity = {
  id: string;
  display_name: string | null;
  username: string | null;
  email: string | null;
  email_verified: boolean;
  avatar_url: string | null;
  bio: string | null;
  locale: string;
  timezone: string;
  currency: string;
  identity_version: number;
  suspended: boolean;
  created_at: string;
  updated_at: string;
};

export type WerseeIdentityPatch = Partial<Pick<WerseeIdentity,
  'display_name' | 'username' | 'avatar_url' | 'bio' | 'locale' | 'timezone' | 'currency'
>>;

type IdentityEnvelope<T> = { data?: T; error?: { message?: string } };

const request = async <T>(session: Session, path: string, init?: RequestInit) => {
  const response = await fetch(`${identityApiUrl}${path}`, {
    ...init,
    headers: {
      Accept: 'application/json',
      Authorization: `Bearer ${session.access_token}`,
      ...(init?.body ? { 'Content-Type': 'application/json' } : {}),
      ...init?.headers,
    },
  });
  const body = await response.json().catch(() => ({})) as IdentityEnvelope<T>;
  if (!response.ok || !body.data) {
    throw new Error(body.error?.message || 'Wersee Identity is temporarily unavailable.');
  }
  return body.data;
};

export const getWerseeIdentity = (session: Session) => request<WerseeIdentity>(session, '/me');

export const updateWerseeIdentity = (session: Session, patch: WerseeIdentityPatch) => (
  request<WerseeIdentity>(session, '/me', { method: 'PATCH', body: JSON.stringify(patch) })
);

