import { useCallback, useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { Link, Navigate, useLocation, useNavigate } from 'react-router-dom';
import {
  AppWindow, ArrowRight, Check, ChevronLeft, Fingerprint, Globe2, KeyRound,
  Loader2, LogOut, MonitorSmartphone, RefreshCw, Save, ShieldCheck, Upload,
  UserRound,
} from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import { OAuthAppsSettings } from '../components/workspace/settings/OAuthAppsSettings';
import { PasskeysSettings } from '../components/workspace/settings/PasskeysSettings';
import { getWerseeIdentity, updateWerseeIdentity, type WerseeIdentity } from '../lib/identity';
import { supabase, supabaseUrl } from '../lib/supabase';

type IdentitySection = 'overview' | 'profile' | 'security' | 'passkeys' | 'sessions' | 'apps';

const sections: { id: IdentitySection; label: string; icon: typeof UserRound }[] = [
  { id: 'overview', label: 'Overview', icon: Globe2 },
  { id: 'profile', label: 'Profile', icon: UserRound },
  { id: 'security', label: 'Security', icon: ShieldCheck },
  { id: 'passkeys', label: 'Passkeys', icon: Fingerprint },
  { id: 'sessions', label: 'Sessions', icon: MonitorSmartphone },
  { id: 'apps', label: 'Connected apps', icon: AppWindow },
];

const serviceDestinations = [
  { name: 'Wersee', url: 'https://www.wersee.com/workspace' },
  { name: 'Community', url: 'https://www.wersee.com/workspace/community' },
  { name: 'Pay', url: 'https://pay.wersee.com' },
  { name: 'Email', url: 'https://email.wersee.com' },
  { name: 'Files', url: 'https://cloud.wersee.com' },
];

const serviceLoginUrl = (destination: string) => {
  const target = new URL('/auth/begin', new URL(destination).origin);
  target.searchParams.set('returnUrl', destination);
  return target.toString();
};

const messageFrom = (error: unknown) => error instanceof Error ? error.message : 'Something went wrong.';

const initials = (identity: WerseeIdentity | null) => {
  const value = identity?.display_name || identity?.username || identity?.email || 'W';
  return value.split(/\s+/).slice(0, 2).map((part) => part[0]).join('').toUpperCase();
};

const Card = ({ children, className = '' }: { children: ReactNode; className?: string }) => (
  <section className={`rounded-[24px] border border-white/10 bg-white/[0.045] p-5 shadow-[0_20px_70px_rgba(0,0,0,0.22)] md:p-6 ${className}`}>{children}</section>
);

const Status = ({ tone = 'neutral', children }: { tone?: 'neutral' | 'success' | 'error'; children: ReactNode }) => (
  <div className={`rounded-2xl border px-4 py-3 text-sm ${tone === 'success' ? 'border-emerald-400/20 bg-emerald-400/10 text-emerald-200' : tone === 'error' ? 'border-red-400/20 bg-red-400/10 text-red-200' : 'border-white/10 bg-white/5 text-white/70'}`}>{children}</div>
);

const ProfileSection = ({ identity, onIdentity }: { identity: WerseeIdentity; onIdentity: (value: WerseeIdentity) => void }) => {
  const { session, refreshAuth } = useAuth();
  const [form, setForm] = useState({
    display_name: identity.display_name || '', username: identity.username || '', bio: identity.bio || '',
    locale: identity.locale || 'en-US', timezone: identity.timezone || 'UTC', currency: identity.currency || 'EUR',
  });
  const [email, setEmail] = useState(identity.email || '');
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [notice, setNotice] = useState<{ tone: 'success' | 'error'; text: string } | null>(null);

  useEffect(() => {
    setForm({ display_name: identity.display_name || '', username: identity.username || '', bio: identity.bio || '', locale: identity.locale, timezone: identity.timezone, currency: identity.currency });
    setEmail(identity.email || '');
  }, [identity]);

  const save = async (event: FormEvent) => {
    event.preventDefault();
    if (!session) return;
    setSaving(true); setNotice(null);
    try {
      const next = await updateWerseeIdentity(session, form);
      if (email.trim().toLowerCase() !== (identity.email || '').toLowerCase()) {
        const { error } = await supabase.auth.updateUser(
          { email: email.trim() },
          { emailRedirectTo: 'https://id.wersee.com/confirm-email?returnUrl=https%3A%2F%2Fid.wersee.com%2Faccount%2Fprofile' },
        );
        if (error) throw error;
        setNotice({ tone: 'success', text: 'Profile saved. Confirm the new address from both email inboxes to finish the email change.' });
      } else {
        setNotice({ tone: 'success', text: 'Your Wersee identity has been updated everywhere.' });
      }
      onIdentity(next);
      await refreshAuth();
    } catch (error) {
      setNotice({ tone: 'error', text: messageFrom(error) });
    } finally { setSaving(false); }
  };

  const uploadAvatar = async (file?: File) => {
    if (!file || !session) return;
    if (!['image/jpeg', 'image/png', 'image/webp', 'image/gif'].includes(file.type) || file.size > 5 * 1024 * 1024) {
      setNotice({ tone: 'error', text: 'Choose a JPG, PNG, WebP, or GIF smaller than 5 MB.' });
      return;
    }
    setUploading(true); setNotice(null);
    try {
      const extension = file.name.split('.').pop()?.toLowerCase().replace(/[^a-z0-9]/g, '') || 'jpg';
      const path = `${session.user.id}/avatar-${Date.now()}.${extension}`;
      const { error } = await supabase.storage.from('identity-avatars').upload(path, file, { contentType: file.type, upsert: false });
      if (error) throw error;
      const avatarUrl = `${supabaseUrl.replace(/\/+$/, '')}/storage/v1/object/public/identity-avatars/${path}`;
      const next = await updateWerseeIdentity(session, { avatar_url: avatarUrl });
      onIdentity(next);
      await refreshAuth();
      setNotice({ tone: 'success', text: 'Your new avatar is now the Wersee-wide avatar.' });
    } catch (error) { setNotice({ tone: 'error', text: messageFrom(error) }); }
    finally { setUploading(false); }
  };

  const input = 'w-full rounded-2xl border border-white/10 bg-black/30 px-4 py-3 text-sm text-white outline-none transition focus:border-violet-400/50 focus:ring-4 focus:ring-violet-500/10';
  return <form onSubmit={save} className="space-y-5">
    <Card>
      <div className="flex flex-col gap-5 sm:flex-row sm:items-center">
        <div className="grid h-24 w-24 shrink-0 place-items-center overflow-hidden rounded-[28px] border border-white/10 bg-gradient-to-br from-violet-500/30 to-blue-500/20 text-2xl font-black text-white">
          {identity.avatar_url ? <img src={identity.avatar_url} alt="" className="h-full w-full object-cover" /> : initials(identity)}
        </div>
        <div><h2 className="text-lg font-bold text-white">Wersee-wide avatar</h2><p className="mt-1 max-w-lg text-sm leading-6 text-white/50">This image is owned by Wersee ID and updates across every connected Wersee service.</p>
          <label className="mt-4 inline-flex cursor-pointer items-center gap-2 rounded-full border border-white/10 bg-white/10 px-4 py-2 text-xs font-semibold text-white hover:bg-white/15">
            {uploading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Upload className="h-4 w-4" />} {uploading ? 'Uploading' : 'Change avatar'}
            <input type="file" accept="image/jpeg,image/png,image/webp,image/gif" className="hidden" disabled={uploading} onChange={(event) => void uploadAvatar(event.target.files?.[0])} />
          </label>
        </div>
      </div>
    </Card>
    <Card className="space-y-5">
      <div><h2 className="text-lg font-bold text-white">Profile and preferences</h2><p className="mt-1 text-sm text-white/50">One canonical profile, used by all Wersee products.</p></div>
      <div className="grid gap-4 md:grid-cols-2">
        <label className="space-y-2 text-xs font-semibold text-white/60">Display name<input className={input} value={form.display_name} required maxLength={160} onChange={(e) => setForm({ ...form, display_name: e.target.value })} /></label>
        <label className="space-y-2 text-xs font-semibold text-white/60">Username<input className={input} value={form.username} required minLength={3} maxLength={32} onChange={(e) => setForm({ ...form, username: e.target.value.toLowerCase() })} /></label>
        <label className="space-y-2 text-xs font-semibold text-white/60 md:col-span-2">Email<input className={input} type="email" value={email} required onChange={(e) => setEmail(e.target.value)} /><span className="block font-normal text-white/35">Email changes require confirmation and are handled by Wersee ID security.</span></label>
        <label className="space-y-2 text-xs font-semibold text-white/60 md:col-span-2">Bio<textarea className={`${input} min-h-24 resize-y`} maxLength={500} value={form.bio} onChange={(e) => setForm({ ...form, bio: e.target.value })} /></label>
        <label className="space-y-2 text-xs font-semibold text-white/60">Language<select className={input} value={form.locale} onChange={(e) => setForm({ ...form, locale: e.target.value })}><option value="en-US">English</option><option value="nl-NL">Nederlands</option><option value="de-DE">Deutsch</option><option value="fr-FR">Français</option></select></label>
        <label className="space-y-2 text-xs font-semibold text-white/60">Timezone<input className={input} value={form.timezone} onChange={(e) => setForm({ ...form, timezone: e.target.value })} /></label>
        <label className="space-y-2 text-xs font-semibold text-white/60">Currency<select className={input} value={form.currency} onChange={(e) => setForm({ ...form, currency: e.target.value })}><option>EUR</option><option>USD</option><option>GBP</option></select></label>
      </div>
      {notice && <Status tone={notice.tone}>{notice.text}</Status>}
      <button disabled={saving} className="inline-flex items-center gap-2 rounded-full bg-white px-5 py-2.5 text-sm font-bold text-black hover:bg-white/90 disabled:opacity-50">{saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />} Save identity</button>
    </Card>
  </form>;
};

const SecuritySection = ({ identity }: { identity: WerseeIdentity }) => {
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [busy, setBusy] = useState(false);
  const [notice, setNotice] = useState<{ tone: 'success' | 'error'; text: string } | null>(null);
  const savePassword = async (event: FormEvent) => {
    event.preventDefault(); setNotice(null);
    if (password.length < 8 || password !== confirm) { setNotice({ tone: 'error', text: 'Use at least 8 characters and make both passwords match.' }); return; }
    setBusy(true);
    const { error } = await supabase.auth.updateUser({ password });
    setBusy(false);
    if (error) setNotice({ tone: 'error', text: error.message });
    else { setPassword(''); setConfirm(''); setNotice({ tone: 'success', text: 'Password updated for your complete Wersee account.' }); }
  };
  return <div className="space-y-5">
    <Card><div className="flex items-start gap-4"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-emerald-400/10 text-emerald-300"><ShieldCheck className="h-5 w-5" /></span><div><h2 className="font-bold text-white">Identity security</h2><p className="mt-1 text-sm leading-6 text-white/50">{identity.email_verified ? 'Your email is verified. Wersee can use it for sign-in verification and account recovery.' : 'Verify your email to fully protect account recovery.'}</p></div></div></Card>
    <Card><form onSubmit={savePassword} className="max-w-xl space-y-4"><div><h2 className="text-lg font-bold text-white">Change password</h2><p className="mt-1 text-sm text-white/50">Changing it here changes it for every Wersee service.</p></div><input type="password" autoComplete="new-password" placeholder="New password" className="w-full rounded-2xl border border-white/10 bg-black/30 px-4 py-3 text-sm text-white outline-none focus:border-violet-400/50" value={password} onChange={(e) => setPassword(e.target.value)} /><input type="password" autoComplete="new-password" placeholder="Confirm new password" className="w-full rounded-2xl border border-white/10 bg-black/30 px-4 py-3 text-sm text-white outline-none focus:border-violet-400/50" value={confirm} onChange={(e) => setConfirm(e.target.value)} />{notice && <Status tone={notice.tone}>{notice.text}</Status>}<button disabled={busy} className="inline-flex items-center gap-2 rounded-full bg-white px-5 py-2.5 text-sm font-bold text-black disabled:opacity-50">{busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <KeyRound className="h-4 w-4" />} Update password</button></form></Card>
  </div>;
};

const SessionsSection = () => {
  const { signOut } = useAuth();
  const [busy, setBusy] = useState<'others' | 'all' | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const others = async () => { setBusy('others'); const { error } = await supabase.auth.signOut({ scope: 'others' }); setBusy(null); setNotice(error ? error.message : 'Other Wersee sessions were revoked.'); };
  return <div className="space-y-5"><Card><div className="flex gap-4"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-blue-400/10 text-blue-300"><MonitorSmartphone className="h-5 w-5" /></span><div><h2 className="font-bold text-white">This browser</h2><p className="mt-1 text-sm text-white/50">Current session · {navigator.userAgent.includes('Mobile') ? 'Mobile browser' : 'Desktop browser'}</p><span className="mt-3 inline-flex items-center gap-1.5 rounded-full bg-emerald-400/10 px-3 py-1 text-xs font-semibold text-emerald-300"><Check className="h-3 w-3" /> Active now</span></div></div></Card><Card className="space-y-4"><div><h2 className="text-lg font-bold text-white">Session controls</h2><p className="mt-1 text-sm text-white/50">Revoke sessions across the complete Wersee account.</p></div>{notice && <Status>{notice}</Status>}<div className="flex flex-wrap gap-3"><button onClick={() => void others()} disabled={Boolean(busy)} className="rounded-full border border-white/10 bg-white/5 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50">{busy === 'others' ? 'Revoking…' : 'Sign out other sessions'}</button><button onClick={() => { setBusy('all'); void signOut(); }} disabled={Boolean(busy)} className="inline-flex items-center gap-2 rounded-full border border-red-400/20 bg-red-400/10 px-4 py-2.5 text-sm font-semibold text-red-200 disabled:opacity-50"><LogOut className="h-4 w-4" /> Sign out everywhere</button></div></Card></div>;
};

export const IdentityCenter = () => {
  const { session, user } = useAuth();
  const location = useLocation();
  const navigate = useNavigate();
  const section = (location.pathname.split('/').filter(Boolean)[1] || 'overview') as IdentitySection;
  const active = sections.some((item) => item.id === section) ? section : 'overview';
  const [identity, setIdentity] = useState<WerseeIdentity | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    if (!session) return;
    setLoading(true); setError(null);
    try { setIdentity(await getWerseeIdentity(session)); }
    catch (loadError) { setError(messageFrom(loadError)); }
    finally { setLoading(false); }
  }, [session]);
  useEffect(() => { void load(); }, [load]);

  useEffect(() => {
    if (session || user) return;
    const target = new URL('/auth', window.location.origin);
    target.searchParams.set('authReturn', window.location.href);
    window.location.replace(target.toString());
  }, [session, user]);

  const title = useMemo(() => sections.find((item) => item.id === active)?.label || 'Overview', [active]);
  if (!session || !user) return <div className="grid min-h-[100dvh] place-items-center bg-[#07070a] text-white"><Loader2 className="h-6 w-6 animate-spin" /></div>;
  if (location.pathname === '/' || location.pathname === '/account') return <Navigate to="/account/overview" replace />;

  return <div className="min-h-[100dvh] bg-[#07070a] text-white">
    <div className="pointer-events-none fixed inset-0 bg-[radial-gradient(circle_at_15%_0%,rgba(124,58,237,0.18),transparent_32%),radial-gradient(circle_at_85%_10%,rgba(37,99,235,0.13),transparent_30%)]" />
    <header className="sticky top-0 z-30 border-b border-white/10 bg-[#07070a]/80 backdrop-blur-2xl"><div className="mx-auto flex max-w-6xl items-center justify-between px-4 py-3 md:px-6"><Link to="/account/overview" className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-[13px] bg-white text-sm font-black text-black">W</span><div><p className="text-sm font-bold">Wersee ID</p><p className="text-[10px] text-white/40">One identity. Every Wersee service.</p></div></Link><a href={serviceLoginUrl('https://www.wersee.com/workspace')} className="inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/5 px-4 py-2 text-xs font-semibold text-white/80 hover:bg-white/10">Open Wersee <ArrowRight className="h-3.5 w-3.5" /></a></div></header>
    <div className="relative mx-auto grid max-w-6xl gap-6 px-4 py-6 md:grid-cols-[230px_minmax(0,1fr)] md:px-6 md:py-10">
      <aside className="md:sticky md:top-24 md:h-fit"><div className="mb-5 flex items-center gap-3 px-2"><div className="grid h-12 w-12 place-items-center overflow-hidden rounded-2xl border border-white/10 bg-white/10 font-bold">{identity?.avatar_url ? <img src={identity.avatar_url} alt="" className="h-full w-full object-cover" /> : initials(identity)}</div><div className="min-w-0"><p className="truncate text-sm font-bold">{identity?.display_name || user.email}</p><p className="truncate text-xs text-white/40">{identity?.username ? `@${identity.username}` : user.email}</p></div></div><nav className="flex gap-2 overflow-x-auto pb-2 md:block md:space-y-1 md:overflow-visible">{sections.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => navigate(`/account/${id}`)} className={`flex shrink-0 items-center gap-3 rounded-full px-4 py-2.5 text-sm font-semibold transition md:w-full md:rounded-2xl ${active === id ? 'bg-white text-black' : 'text-white/55 hover:bg-white/5 hover:text-white'}`}><Icon className="h-4 w-4" />{label}</button>)}</nav></aside>
      <main className="min-w-0"><div className="mb-6"><button onClick={() => navigate('/account/overview')} className={`mb-3 items-center gap-1 text-xs text-white/45 ${active === 'overview' ? 'hidden' : 'inline-flex'}`}><ChevronLeft className="h-3.5 w-3.5" /> Account</button><h1 className="text-2xl font-black tracking-tight md:text-3xl">{title}</h1><p className="mt-2 text-sm text-white/45">Managed centrally by id.wersee.com</p></div>
        {loading ? <Card className="grid min-h-64 place-items-center"><Loader2 className="h-6 w-6 animate-spin text-white/50" /></Card> : error || !identity ? <Card className="space-y-4"><Status tone="error">{error || 'Identity unavailable.'}</Status><button onClick={() => void load()} className="inline-flex items-center gap-2 rounded-full bg-white px-4 py-2 text-sm font-bold text-black"><RefreshCw className="h-4 w-4" /> Retry</button></Card> : <>
          {active === 'overview' && <div className="space-y-5"><Card><div className="flex flex-col gap-5 sm:flex-row sm:items-center"><div className="grid h-20 w-20 place-items-center overflow-hidden rounded-[25px] border border-white/10 bg-gradient-to-br from-violet-500/30 to-blue-500/20 text-xl font-black">{identity.avatar_url ? <img src={identity.avatar_url} alt="" className="h-full w-full object-cover" /> : initials(identity)}</div><div className="flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className="text-xl font-black">{identity.display_name || identity.email}</h2><span className="rounded-full bg-emerald-400/10 px-2.5 py-1 text-[10px] font-bold text-emerald-300">WERSEE ID ACTIVE</span></div><p className="mt-1 text-sm text-white/45">{identity.email} · ID {identity.id}</p><p className="mt-3 max-w-xl text-sm leading-6 text-white/55">This is your canonical Wersee identity. Profile, preferences, security, and connected apps are controlled here.</p></div></div></Card><div className="grid gap-4 sm:grid-cols-2">{sections.slice(1).map(({ id, label, icon: Icon }) => <button key={id} onClick={() => navigate(`/account/${id}`)} className="group rounded-[22px] border border-white/10 bg-white/[0.04] p-5 text-left hover:bg-white/[0.07]"><div className="flex items-center justify-between"><span className="grid h-10 w-10 place-items-center rounded-2xl bg-white/10"><Icon className="h-5 w-5" /></span><ArrowRight className="h-4 w-4 text-white/25 transition group-hover:translate-x-1 group-hover:text-white" /></div><h3 className="mt-5 font-bold">{label}</h3></button>)}</div><Card><h2 className="font-bold">Continue with Wersee</h2><p className="mt-1 text-sm text-white/45">Open a service through its own secure OAuth handoff.</p><div className="mt-4 flex flex-wrap gap-2">{serviceDestinations.map((service) => <a key={service.name} href={serviceLoginUrl(service.url)} className="rounded-full border border-white/10 bg-white/5 px-4 py-2 text-xs font-semibold hover:bg-white/10">{service.name}</a>)}</div></Card></div>}
          {active === 'profile' && <ProfileSection identity={identity} onIdentity={setIdentity} />}
          {active === 'security' && <SecuritySection identity={identity} />}
          {active === 'passkeys' && <PasskeysSettings user={user} />}
          {active === 'sessions' && <SessionsSection />}
          {active === 'apps' && <OAuthAppsSettings />}
        </>}
      </main>
    </div>
  </div>;
};
